window.PROBLEM_SOURCES["react-01"] = {"id": "react-01", "language": "react", "stub": {"path": "react/practice_problems/problem_01_activity_feed.jsx", "source": "/**\n * =============================================================================\n * INTERVIEW PROBLEM 3: Live Activity Feed with Filtering & Optimistic Updates\n * Difficulty: Senior Software Engineer | Estimated time: 45-60 min\n * =============================================================================\n *\n * CONTEXT\n * -------\n * You're building the activity feed for a SaaS developer platform — think\n * Stripe's event log, Linear's notification inbox, or Grafana's alert history.\n *\n * The backend pushes events over a persistent connection (simulated below).\n * Users need to filter the feed and acknowledge events inline.\n *\n * A working mock event source and basic styles are provided. Do not modify\n * anything in the \"PROVIDED — DO NOT MODIFY\" sections.\n *\n * =============================================================================\n *\n * PART 1 — Live event subscription  (~15 min)\n * ─────────────────────────────────────────────\n * Render an <ActivityFeed /> component that:\n *   - Subscribes to `eventSource` on mount and unsubscribes on unmount.\n *   - Displays incoming events in reverse-chronological order (newest on top).\n *   - Each event row shows: timestamp, type badge, actor, and message.\n *   - New events should appear at the top without losing scroll position for\n *     events already in view. (Hint: prepend, don't append.)\n *\n * PART 2 — Client-side filtering  (~15 min)\n * ──────────────────────────────────────────\n * Add filter controls above the feed:\n *   - A dropdown (or set of toggle buttons) for EVENT TYPE\n *     (values: \"all\" | \"deploy\" | \"alert\" | \"payment\" | \"auth\")\n *   - A dropdown for STATUS (\"all\" | \"success\" | \"warning\" | \"error\")\n *\n * Requirements:\n *   - Filtering is purely client-side — all events stay in memory.\n *   - Changing a filter must NOT restart the event subscription.\n *   - Use useMemo (or equivalent) so the filtered list is only recomputed\n *     when events or filter state actually change.\n *\n * PART 3 — Optimistic acknowledgement  (~15 min)\n * ────────────────────────────────────────────────\n * Add an \"Ack\" button to each unacknowledged event row.\n *\n * When clicked:\n *   1. Immediately mark the event as acknowledged in local state (optimistic).\n *   2. Call `acknowledgeEvent(eventId)` — it returns a Promise that resolves\n *      on success or rejects ~20% of the time to simulate flakiness.\n *   3. On rejection: revert the event to unacknowledged and display an inline\n *      error message on that row (\"Failed — try again\").\n *   4. While the request is in-flight, the button should show a loading state\n *      and be disabled to prevent double-submission.\n *\n * =============================================================================\n */\n\nimport React, { useState, useEffect, useMemo, useRef, useCallback } from \"react\";\n\n// =============================================================================\n// PROVIDED — DO NOT MODIFY\n// =============================================================================\n\nconst EVENT_TYPES = [\"deploy\", \"alert\", \"payment\", \"auth\"];\nconst STATUSES = [\"success\", \"warning\", \"error\"];\nconst ACTORS = [\"ci-bot\", \"alice@corp.com\", \"webhooks-service\", \"billing-worker\", \"bob@corp.com\"];\nconst MESSAGES = {\n  deploy: [\"Deployed v2.4.1 to production\", \"Rollback triggered on staging\", \"Build pipeline completed\"],\n  alert:  [\"CPU usage exceeded 90%\", \"Error rate spike detected\", \"Latency p99 > 2s\"],\n  payment: [\"Invoice #8821 paid\", \"Subscription renewed\", \"Payment method declined\"],\n  auth:   [\"API key created\", \"OAuth token revoked\", \"Login from new IP\"],\n};\n\nlet _eventId = 1;\n\n/**\n * createEventSource() → { connect, disconnect, subscribe }\n *\n * connect()           — start emitting events (~every 1.5s)\n * disconnect()        — stop emitting\n * subscribe(handler)  — register a handler; returns an unsubscribe function\n *                       handler receives an event object (see shape below)\n *\n * Event shape:\n * {\n *   id:            string,   // unique identifier\n *   type:          string,   // \"deploy\" | \"alert\" | \"payment\" | \"auth\"\n *   status:        string,   // \"success\" | \"warning\" | \"error\"\n *   actor:         string,   // who/what triggered the event\n *   message:       string,\n *   timestamp:     string,   // ISO 8601\n *   acknowledged:  false,    // always false when emitted\n * }\n */\nexport function createEventSource() {\n  let handlers = [];\n  let timerId = null;\n\n  function emit() {\n    const type = EVENT_TYPES[Math.floor(Math.random() * EVENT_TYPES.length)];\n    const event = {\n      id:           `evt-${_eventId++}`,\n      type,\n      status:       STATUSES[Math.floor(Math.random() * STATUSES.length)],\n      actor:        ACTORS[Math.floor(Math.random() * ACTORS.length)],\n      message:      MESSAGES[type][Math.floor(Math.random() * MESSAGES[type].length)],\n      timestamp:    new Date().toISOString(),\n      acknowledged: false,\n    };\n    handlers.forEach((h) => h(event));\n  }\n\n  return {\n    connect:    () => { timerId = setInterval(emit, 1500); },\n    disconnect: () => { clearInterval(timerId); timerId = null; },\n    subscribe:  (handler) => {\n      handlers.push(handler);\n      return () => { handlers = handlers.filter((h) => h !== handler); };\n    },\n  };\n}\n\n/**\n * acknowledgeEvent(eventId) → Promise<void>\n * Simulates a PATCH /events/:id API call.\n * Resolves after ~400ms. Rejects ~20% of the time.\n */\nexport function acknowledgeEvent(eventId) {\n  return new Promise((resolve, reject) => {\n    setTimeout(() => {\n      if (Math.random() < 0.2) {\n        reject(new Error(`Failed to acknowledge ${eventId}`));\n      } else {\n        resolve();\n      }\n    }, 400);\n  });\n}\n\n// Shared event source instance — import this in your component\nexport const eventSource = createEventSource();\n\n// =============================================================================\n// YOUR WORK STARTS HERE\n// =============================================================================\n\n/**\n * STATUS_COLORS and TYPE_LABELS are helpers you may use for styling.\n * Feel free to add your own or ignore these.\n */\nconst STATUS_COLORS = {\n  success: \"#22c55e\",\n  warning: \"#f59e0b\",\n  error:   \"#ef4444\",\n};\n\nconst TYPE_LABELS = {\n  deploy:  \"Deploy\",\n  alert:   \"Alert\",\n  payment: \"Payment\",\n  auth:    \"Auth\",\n};\n\n// ---------------------------------------------------------------------------\n// PART 1 — Implement ActivityFeed\n// ---------------------------------------------------------------------------\n\nexport function ActivityFeed() {\n  // TODO Part 1: subscribe to eventSource on mount, unsubscribe on unmount.\n  //              Store events in state and render them newest-first.\n\n  // TODO Part 2: add filter state (type, status) and filter the event list\n  //              with useMemo. Render filter controls above the list.\n  //              The subscription must NOT restart when filters change.\n\n  // TODO Part 3: implement optimistic acknowledgement.\n  //              Track per-event loading and error state.\n  //              Call acknowledgeEvent(), revert + show error on failure.\n\n  return (\n    <div style={{ fontFamily: \"monospace\", maxWidth: 700, margin: \"0 auto\", padding: 24 }}>\n      <h2 style={{ marginBottom: 16 }}>Activity Feed</h2>\n\n      {/* TODO: filter controls go here */}\n\n      {/* TODO: event list goes here */}\n      <p style={{ color: \"#888\" }}>No events yet.</p>\n    </div>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// Suggested sub-components (optional — structure however you like)\n// ---------------------------------------------------------------------------\n\n// function FilterBar({ typeFilter, statusFilter, onTypeChange, onStatusChange }) { ... }\n\n// function EventRow({ event, onAcknowledge }) { ... }\n\n// ---------------------------------------------------------------------------\n// App entry point — renders the feed\n// ---------------------------------------------------------------------------\n\nexport default function App() {\n  // Connect the event source once when the app mounts\n  useEffect(() => {\n    eventSource.connect();\n    return () => eventSource.disconnect();\n  }, []);\n\n  return <ActivityFeed />;\n}\n\n/**\n * =============================================================================\n * SETUP NOTE\n * =============================================================================\n * To run this in a browser, create a Vite React project and drop this file in:\n *\n *   npm create vite@latest interview-react -- --template react\n *   cd interview-react\n *   # replace src/App.jsx with this file (or import ActivityFeed from it)\n *   npm install && npm run dev\n *\n * Or with Create React App:\n *   npx create-react-app interview-react\n *   # replace src/App.js with this file\n *   npm start\n * =============================================================================\n */\n"}, "test": {"path": "react/tests/test_problem_01_activity_feed.spec.js", "source": "/**\n * Playwright tests for Problem 01 — Activity Feed\n *\n * Run (from react/):\n *   npm run test:01\n *\n * These tests target a COMPLETED implementation of src/App.jsx.\n * Against the stub they will fail — that is expected behaviour.\n *\n * Copy the problem to activate:\n *   cp practice_problems/problem_01_activity_feed.jsx src/App.jsx\n *\n * Determinism: these tests own the page's clock and `Math.random` (see\n * tests/helpers/deterministic.js). Problem 01 has no seed data — its only\n * source is a 1500 ms interval — so each test advances the clock by an exact\n * number of intervals and knows precisely how many events exist.\n *\n * With `Math.random` pinned to RANDOM_SUCCESS (0.5) the generator produces a\n * known event: EVENT_TYPES[floor(0.5 * 4)] = \"payment\" with\n * STATUSES[floor(0.5 * 3)] = \"warning\". That makes the filter assertions\n * two-sided — matching filter keeps rows, non-matching filter empties them —\n * rather than the previous \"the app did not crash\".\n *\n * Problem 01 specifies no data-testid contract, so these tests keep to the\n * role and text selectors a candidate can infer from the stub. Event count is\n * read from the Ack buttons, since the stub requires one per unacknowledged row.\n */\n\nimport { test, expect } from '@playwright/test'\nimport { installDeterminism, advanceClock, settleRequest, RANDOM_FAILURE } from './helpers/deterministic.js'\n\nconst HEADING = /activity feed/i\nconst EMIT_INTERVAL_MS = 1500\n\n/** The event the pinned generator produces, and one it never produces. */\nconst GENERATED_TYPE = 'payment'\nconst OTHER_TYPE = 'deploy'\n\nconst ackButtons = page => page.getByRole('button', { name: /ack/i })\n\n/** The type dropdown, identified by its options rather than by DOM order. */\nconst typeFilter = page =>\n  page.locator('select').filter({ has: page.locator(`option[value=\"${GENERATED_TYPE}\"]`) }).first()\n\ntest.describe('Problem 01 — Activity Feed', () => {\n  test.beforeEach(async ({ page }) => {\n    await installDeterminism(page)\n  })\n\n  // ── Part 1: live subscription ──────────────────────────────────────────────\n\n  test('renders the Activity Feed heading', async ({ page }) => {\n    await expect(page.getByRole('heading', { name: HEADING })).toBeVisible()\n  })\n\n  test('shows the empty state until the source emits', async ({ page }) => {\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await expect(page.locator('body')).toContainText('No events yet')\n  })\n\n  test('events appear after the source connects', async ({ page }) => {\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await advanceClock(page, EMIT_INTERVAL_MS)\n    await expect(page.locator('body')).not.toContainText('No events yet')\n    await expect(ackButtons(page)).toHaveCount(1)\n  })\n\n  test('events accumulate one per interval', async ({ page }) => {\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await advanceClock(page, EMIT_INTERVAL_MS * 3)\n    // Exact, not \"at least\": the clock only ticked three intervals.\n    await expect(ackButtons(page)).toHaveCount(3)\n  })\n\n  // ── Part 2: client-side filtering ─────────────────────────────────────────\n\n  test('filter controls are rendered', async ({ page }) => {\n    await expect(page.locator('select').first()).toBeVisible()\n  })\n\n  test('filtering to the emitted type keeps the events visible', async ({ page }) => {\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await advanceClock(page, EMIT_INTERVAL_MS * 2)\n    await typeFilter(page).selectOption(GENERATED_TYPE)\n    await expect(ackButtons(page)).toHaveCount(2)\n  })\n\n  test('filtering to a type with no events empties the list', async ({ page }) => {\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await advanceClock(page, EMIT_INTERVAL_MS * 2)\n    await typeFilter(page).selectOption(OTHER_TYPE)\n    await expect(ackButtons(page)).toHaveCount(0)\n  })\n\n  test('changing a filter does not restart the subscription', async ({ page }) => {\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await advanceClock(page, EMIT_INTERVAL_MS * 2)\n    await expect(ackButtons(page)).toHaveCount(2)\n\n    await typeFilter(page).selectOption(OTHER_TYPE)\n    await typeFilter(page).selectOption('all')\n    // Events already received survive the filter round-trip...\n    await expect(ackButtons(page)).toHaveCount(2)\n\n    // ...and the feed is still delivering into the same list.\n    await advanceClock(page, EMIT_INTERVAL_MS)\n    await expect(ackButtons(page)).toHaveCount(3)\n  })\n\n  // ── Part 3: optimistic acknowledgement ────────────────────────────────────\n\n  test('Ack button appears on event rows', async ({ page }) => {\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await advanceClock(page, EMIT_INTERVAL_MS)\n    await expect(ackButtons(page).first()).toBeVisible()\n  })\n\n  test('Ack button is disabled immediately after clicking', async ({ page }) => {\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await advanceClock(page, EMIT_INTERVAL_MS)\n    const btn = ackButtons(page).first()\n    await btn.click()\n    // The request cannot settle: no time passes until a test advances it.\n    await expect(btn).toBeDisabled()\n  })\n\n  test('a successful ack removes the Ack button from that row', async ({ page }) => {\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await advanceClock(page, EMIT_INTERVAL_MS)\n    await ackButtons(page).first().click()\n    await settleRequest(page)\n    // 600 ms of settle time stays short of the next 1500 ms emission, so the\n    // only possible change to the count is the ack itself.\n    await expect(ackButtons(page)).toHaveCount(0)\n  })\n\n  test('a rejected ack reverts the row and shows an inline error', async ({ page }) => {\n    // Previously untestable: the reject branch fired at random. Pinning\n    // Math.random below the 0.2 threshold makes the rollback path assertable.\n    await installDeterminism(page, { random: RANDOM_FAILURE })\n    await page.getByRole('heading', { name: HEADING }).waitFor()\n    await advanceClock(page, EMIT_INTERVAL_MS)\n    await ackButtons(page).first().click()\n    await settleRequest(page)\n    await expect(page.locator('body')).toContainText(/failed/i)\n    await expect(ackButtons(page)).toHaveCount(1)\n    await expect(ackButtons(page).first()).toBeEnabled()\n  })\n})\n"}, "parts": [{"part": 1, "source": " * PART 1 — Live event subscription  (~15 min)\n * ─────────────────────────────────────────────\n * Render an <ActivityFeed /> component that:\n *   - Subscribes to `eventSource` on mount and unsubscribes on unmount.\n *   - Displays incoming events in reverse-chronological order (newest on top).\n *   - Each event row shows: timestamp, type badge, actor, and message.\n *   - New events should appear at the top without losing scroll position for\n *     events already in view. (Hint: prepend, don't append.)\n *\n *\n"}, {"part": 2, "source": " * PART 2 — Client-side filtering  (~15 min)\n * ──────────────────────────────────────────\n * Add filter controls above the feed:\n *   - A dropdown (or set of toggle buttons) for EVENT TYPE\n *     (values: \"all\" | \"deploy\" | \"alert\" | \"payment\" | \"auth\")\n *   - A dropdown for STATUS (\"all\" | \"success\" | \"warning\" | \"error\")\n *\n * Requirements:\n *   - Filtering is purely client-side — all events stay in memory.\n *   - Changing a filter must NOT restart the event subscription.\n *   - Use useMemo (or equivalent) so the filtered list is only recomputed\n *     when events or filter state actually change.\n *\n *\n"}, {"part": 3, "source": " * PART 3 — Optimistic acknowledgement  (~15 min)\n * ────────────────────────────────────────────────\n * Add an \"Ack\" button to each unacknowledged event row.\n *\n * When clicked:\n *   1. Immediately mark the event as acknowledged in local state (optimistic).\n *   2. Call `acknowledgeEvent(eventId)` — it returns a Promise that resolves\n *      on success or rejects ~20% of the time to simulate flakiness.\n *   3. On rejection: revert the event to unacknowledged and display an inline\n *      error message on that row (\"Failed — try again\").\n *   4. While the request is in-flight, the button should show a loading state\n *      and be disabled to prevent double-submission.\n *\n"}], "implementationSurface": "}\n\n      {/* TODO: event list goes here */}\n      <p style={{ color: \"#888\" }}>No events yet.</p>\n    </div>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// Suggested sub-components (optional — structure however you like)\n// ---------------------------------------------------------------------------\n\n// function FilterBar({ typeFilter, statusFilter, onTypeChange, onStatusChange }) { ... }\n\n// function EventRow({ event, onAcknowledge }) { ... }\n\n// ---------------------------------------------------------------------------\n// App entry point — renders the feed\n// ---------------------------------------------------------------------------\n\nexport default function App() {\n  // Connect the event source once when the app mounts\n  useEffect(() => {\n    eventSource.connect();\n    return () => eventSource.disconnect();\n  }, []);\n\n  return <ActivityFeed />;\n}\n\n/**\n * =============================================================================\n * SETUP NOTE\n * =============================================================================\n * To run this in a browser, create a Vite React project and drop this file in:\n *\n *   npm create vite@latest interview-react -- --template react\n *   cd interview-react\n *   # replace src/App.jsx with this file (or import ActivityFeed from it)\n *   npm install && npm run dev\n *\n * Or with Create React App:\n *   npx create-react-app interview-react\n *   # replace src/App.js with this file\n *   npm start\n * =============================================================================\n */\n"};
